/// @brief Enumeration for error codes of a message port.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 2.3.1 @endif
abstract class message_port_error_e {
  /// < Successful
  static const int MESSAGE_PORT_ERROR_NONE = 0;

  /// < Internal I/O error
  static const int MESSAGE_PORT_ERROR_IO_ERROR = -5;

  /// < Out of memory
  static const int MESSAGE_PORT_ERROR_OUT_OF_MEMORY = -12;

  /// < Invalid parameter
  static const int MESSAGE_PORT_ERROR_INVALID_PARAMETER = -22;

  /// < The message port of the remote application is not found
  static const int MESSAGE_PORT_ERROR_PORT_NOT_FOUND = -18022399;

  /// < The remote application is not signed with the same certificate
  static const int MESSAGE_PORT_ERROR_CERTIFICATE_NOT_MATCH = -18022398;

  /// < The size of the message has exceeded the maximum limit
  static const int MESSAGE_PORT_ERROR_MAX_EXCEEDED = -18022397;

  /// < Resource is temporarily unavailable
  static const int MESSAGE_PORT_ERROR_RESOURCE_UNAVAILABLE = -18022396;
}

